import{_ as a,o as s,c as t,ak as i}from"./chunks/framework.CDOtKl_0.js";const k=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cli.md","filePath":"guide/cli.md","lastUpdated":1795699058000}'),l={name:"guide/cli.md"};function o(n,e,d,p,r,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p>Roll dice directly in your terminal with the <a href="https://github.com/dice-roller/cli" target="_blank" rel="noreferrer">RPG Dice Roller CLI</a>. Use it to make individual rolls, roll several expressions at once, or play an interactive dice game.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Install the CLI globally using npm:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @dice-roller/cli</span></span></code></pre></div><p>This makes the <code>roller</code> command available in your terminal.</p><h2 id="roll-dice" tabindex="-1">Roll dice <a class="header-anchor" href="#roll-dice" aria-label="Permalink to &quot;Roll dice&quot;">​</a></h2><p>Pass a <a href="./notation/">dice notation</a> to <code>roller</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;4d6&#39;</span></span></code></pre></div><p>You can also roll several expressions in one command, separated by spaces:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;2d10&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;7d%&#39;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;5dF&#39;</span></span></code></pre></div><p>In Bash, put each notation argument in single quotes to pass spaces and shell characters such as <code>!</code> and <code>&gt;</code> through to the CLI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;4d6 # roll description&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;4d6d1!&gt;=3&#39;</span></span></code></pre></div><p>All supported dice notation is available in the CLI.</p><p>Rolling dice is the default command, so <code>roller &#39;4d6&#39;</code> and <code>roller roll &#39;4d6&#39;</code> are equivalent.</p><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>roller &lt;notation..&gt; [options]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>-s</code>, <code>--separator</code></td><td>Text used to separate the output of multiple rolls.</td><td><code>&quot;; &quot;</code></td></tr><tr><td><code>-e</code>, <code>--engine</code></td><td>Choose <code>crypto</code>, <code>mersenne</code>, <code>nativeMath</code> or <code>xoroshiro128plus</code>.</td><td><code>nativeMath</code></td></tr><tr><td><code>--seed</code></td><td>A signed 32-bit integer seed for <code>mersenne</code> or <code>xoroshiro128plus</code>. Supply the engine with <code>--engine</code>.</td><td></td></tr><tr><td><code>-f</code>, <code>--format</code></td><td>Choose <code>string</code>, <code>json</code>, <code>base64</code> or <code>object</code>. The <code>object</code> format displays a JavaScript object for inspection.</td><td><code>&quot;string&quot;</code></td></tr><tr><td><code>--result-only</code></td><td>With <code>string</code> output, print only the combined total.</td><td><code>false</code></td></tr><tr><td><code>--color</code>, <code>--no-color</code></td><td>Force or disable ANSI styling for text rolls.</td><td>Automatic</td></tr></tbody></table><p>Text rolls use colour when the output terminal supports it. Piped or redirected output is plain text by default. Set <code>NO_COLOR</code> or use <code>--no-color</code> to turn off styling. Exports and <code>--result-only</code> totals are always plain.</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p>Use the Mersenne Twister engine with a seed for repeatable rolls. See <a href="./customisation/random-number-generator.html#use-a-seed-for-repeatable-rolls">random number generators</a> for details.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;4d6&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --engine=mersenne</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seed=415</span></span></code></pre></div><p>Print just the total.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;2d20&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --result-only</span></span></code></pre></div><p>Export the roll history as JSON or Base64-encoded JSON.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;6d8*4&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;6d8*4&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --format=base64</span></span></code></pre></div><h2 id="play-an-interactive-game" tabindex="-1">Play an interactive game <a class="header-anchor" href="#play-an-interactive-game" aria-label="Permalink to &quot;Play an interactive game&quot;">​</a></h2><p>Start an interactive dice game:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play</span></span></code></pre></div><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--players</code></td><td>Player names, separated by spaces.</td></tr><tr><td><code>--count</code></td><td>The number of players.</td></tr><tr><td><code>--color</code>, <code>--no-color</code></td><td>Force or disable ANSI styling for displayed rolls.</td></tr></tbody></table><h3 id="examples-1" tabindex="-1">Examples <a class="header-anchor" href="#examples-1" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><p>Start a game with four players:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --count=4</span></span></code></pre></div><p>Start a game with two players named Barbara and Ian:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --players=Barbara</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ian</span></span></code></pre></div><p>Set the number of players and name only the first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --count=2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --players=Susan</span></span></code></pre></div><h2 id="help-and-version" tabindex="-1">Help and version <a class="header-anchor" href="#help-and-version" aria-label="Permalink to &quot;Help and version&quot;">​</a></h2><p>Show the available commands and options:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>Show help for the interactive game:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> play</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>Display the installed CLI version:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roller</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>You can also use <code>-V</code> instead of <code>--version</code>.</p><h2 id="upgrade-from-cli-v1" tabindex="-1">Upgrade from CLI v1 <a class="header-anchor" href="#upgrade-from-cli-v1" aria-label="Permalink to &quot;Upgrade from CLI v1&quot;">​</a></h2><ul><li><strong>Exports use the RPG Dice Roller v6 schema.</strong> JSON exports now have <code>type: &quot;history&quot;</code> and a top-level <code>rolls</code> array in place of <code>log</code>. Each roll contains a <code>result</code> tree. The same schema applies to Base64 and object output. Update scripts that read the old structure. The format names <code>JSON</code>, <code>BASE_64</code> and <code>OBJECT</code> are still accepted.</li><li><strong>Engine names and seeded sequences have changed.</strong> Use <code>mersenne</code> in place of <code>MersenneTwister19937</code> and <code>crypto</code> in place of <code>nodeCrypto</code> or <code>browserCrypto</code>. A v1 seed can produce different rolls in v2.</li><li><strong>Check your Node.js version</strong> against the <a href="#install">installation requirements</a> before upgrading.</li></ul>`,48)])])}const g=a(l,[["render",o]]);export{k as __pageData,g as default};
